<?php include '../includes/header.php';$u=user();if($u['institution_type']!=='wastigruh'&&!is_admin()&&!is_sub_officer())exit('Wastigruh only.');$code=$u['institution_code'];if(is_admin()||is_sub_officer())$code=$_GET['institution_code']??$code;$s=mysqli_prepare($conn,"SELECT * FROM wastigruh_inventory WHERE institution_code=? ORDER BY category,item_name");mysqli_stmt_bind_param($s,'s',$code);mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);?>
<div class="page-head"><div><p class="eyebrow">WASTIGRUH ASSETS</p><h1>Accessories & Stock Status</h1><p class="muted">Track utensils, furniture, kitchen items, clothing, sports and other hostel assets.</p></div></div><div class="card"><form method="post" action="inventory_save.php"><?=csrf_field()?><input type="hidden" name="institution_code" value="<?=e($code)?>"><div class="grid two"><div><label>Category</label><select name="category"><option>Kitchen</option><option>Furniture</option><option>Clothing</option><option>Bedding</option><option>Sports</option><option>Study</option><option>Electrical</option><option>Sanitation</option><option>Safety</option><option>Other</option></select></div><div><label>Item / Accessory</label><input name="item_name" placeholder="Plates, beds, uniforms, footballs..." required></div><div><label>Total Qty</label><input type="number" name="total_qty" min="0" required></div><div><label>Good Qty</label><input type="number" name="good_qty" min="0" required></div><div><label>Damaged Qty</label><input type="number" name="damaged_qty" min="0" value="0"></div><div><label>Shortage Qty</label><input type="number" name="shortage_qty" min="0" value="0"></div></div><label>Remarks</label><textarea name="remarks" rows="2"></textarea><button>Add / Update Stock Item</button></form></div><div class="card table-wrap"><table><tr><th>Category</th><th>Item</th><th>Total</th><th>Good</th><th>Damaged</th><th>Shortage</th><th>Status</th></tr><?php while($x=mysqli_fetch_assoc($r)):$status=($x['shortage_qty']>0?'shortage':($x['damaged_qty']>0?'attention':'good'));?><tr><td><?=e($x['category'])?></td><td><b><?=e($x['item_name'])?></b><br><small><?=e($x['remarks'])?></small></td><td><?=e($x['total_qty'])?></td><td><?=e($x['good_qty'])?></td><td><?=e($x['damaged_qty'])?></td><td><?=e($x['shortage_qty'])?></td><td><span class="pill <?=$status==='good'?'verified':'warning'?>"><?=e($status)?></span></td></tr><?php endwhile;?></table></div><?php include '../includes/footer.php';?>
